#include "platform.hpp"
#include "voice_test.hpp"
#include "integration.hpp"
#include <fstream>
#include <iostream>
#include <unistd.h>
namespace rc {
static void require(bool condition,const std::string& message){if(!condition)throw std::runtime_error(message);}
static void near(double a,double b){require(std::abs(a-b)<0.0001,"valores diferentes: "+std::to_string(a)+" / "+std::to_string(b));}
template<class F> static void rejects(F f){bool caught=false;try{f();}catch(const std::exception&){caught=true;}require(caught,"a operação deveria ser recusada");}
static Choice find_choice(const std::vector<Choice>& choices,const std::string& name){for(const auto& c:choices)if(c.route_name==name)return c;throw std::runtime_error("rota não encontrada: "+name);}
int tests(){
    int passed=0,failed=0;
    auto test=[&](const char* title,std::function<void()> run){try{run();++passed;std::cout<<"OK  "<<title<<'\n';}catch(const std::exception& e){++failed;std::cout<<"ERRO "<<title<<": "<<e.what()<<'\n';}};
    std::string fixture=read_file(folder()/"testes/sessao.json");Graph base=read_graph(fixture);State original=base.state();Json fixture_json=Json::parse(fixture);
    test("JSON: Unicode, escapes e números",[]{Json j=Json::parse(R"({"s":"\u00c1udio \ud83c\udfa7\n","n":-2.5e-2})");require(j["s"].text()=="Áudio 🎧\n","Unicode incorreto");near(j["n"].number(),-.025);require(Json::parse(j.dump())==j,"roundtrip");});
    test("JSON: rejeitar entrada truncada, NaN e profundidade excessiva",[]{for(const char* j:{"[1,]","{\"x\":}","01","1e999","\"\\ud800\""})rejects([&](){Json::parse(j);});rejects([](){Json::parse(std::string(70,'[')+"0"+std::string(70,']'));});});
    test("Monitor: bytes partidos, strings com colchetes e múltiplos lotes",[]{JsonStream stream;int n=0;std::string input=R"([{"id":1,"x":"á[]{}\""}][{"id":1}])";for(char c:input)stream.feed(std::string_view(&c,1),[&](const Json&){++n;});require(n==2&&stream.batches==2&&stream.empty(),"enquadramento incorreto");});
    test("Monitor: recusar listas e objetos inválidos",[]{JsonStream f;rejects([&](){f.feed("[{},]",[](const Json&){});});});
    test("Volume real: 0.063997 linear corresponde a 40%",[&](){require(original.sink.has_value(),"sem saída");near(original.sink->volume,.4);require(!original.sink->muted,"mudo inesperado");});
    test("Filtro: padrão filtrado e mudo físico independentes",[&](){require(original.filtered&&original.source&&original.physical,"filtro não identificado");require(original.source->ref.name=="filtro_ruido_noise"&&original.physical->muted&&!original.source->muted,"mudos confundidos");});
    test("P2: porta compartilhada com alto-falante, disponibilidade real",[&](){auto speaker=find_choice(original.outputs,"analog-output-speaker");auto phones=find_choice(original.outputs,"analog-output-headphones");require(speaker.node==phones.node&&speaker.available&&!phones.available,"portas incorretas");require(original.inputs.size()==3,"entradas incorretas");});
    test("Aplicativo: destino vindo da ligação PipeWire",[&](){auto apps=original.apps();require(apps.size()==1&&apps[0].label=="Firefox","agrupamento");require(apps[0].nodes[0].output==original.sink->ref.name,"ligação perdida");});
    test("Padrão ausente: não inventar primeiro dispositivo",[&](){Graph g;for(const auto& j:fixture_json.items())if(j["type"].text().find(":Metadata")==std::string::npos)g.update(j);auto s=g.state();require(!s.sink&&!s.source,"padrão inventado");});
    test("Padrão ausente: nó parcial sem nome também permanece sem padrão",[]{Graph g;g.update(Json::parse(R"({"id":1,"type":"PipeWire:Interface:Node","info":{"props":{"object.serial":123,"media.class":"Audio/Sink"}}})"));require(!g.state().sink,"nó parcial virou padrão sem metadados");});
    test("Hotplug: remoção id-only e info:null",[&](){Graph g=base;g.update(Json::parse("{\"id\":111}"));require(g.state().apps().empty(),"app removido retido");g.update(Json::parse("{\"id\":62,\"info\":null}"));require(!g.state().sink,"saída removida retida");});
    test("Atualização parcial: preservar volume da rota de hardware",[&](){Graph g=base;g.update(Json::parse("{\"id\":62,\"info\":{\"params\":{\"Props\":[{\"channelVolumes\":[0.125]}]}}}"));near(g.state().sink->volume,.4);});
    test("Metadados: remover só a chave correspondente",[&](){Graph g=base;g.update(Json::parse("{\"id\":44,\"metadata\":[{\"subject\":0,\"key\":\"default.audio.source\",\"value\":null}]}"));require(!g.state().source&&g.state().sink,"apagou padrões indevidos");});
    test("Metadados: limpeza por subject",[&](){Graph g=base;g.update(Json::parse("{\"id\":44,\"metadata\":[{\"subject\":0,\"key\":null}]}"));require(!g.state().source&&!g.state().sink,"limpeza incompleta");});
    test("Links: ligação pode chegar antes dos nós",[&](){Graph g;Json::Array links,other;for(const auto& j:fixture_json.items())(j["type"].text().find(":Link")!=std::string::npos?links:other).push_back(j);for(const auto& j:links)g.update(j);for(const auto& j:other)g.update(j);require(g.state().apps()[0].nodes[0].output==original.sink->ref.name,"ordem alterou destino");});
    test("Cache: descartar vídeo e propriedades de formato",[&](){Graph g=base;size_t size=g.size();g.update(Json::parse(R"({"id":9999,"type":"PipeWire:Interface:Node","info":{"props":{"media.class":"Video/Source"},"params":{"EnumFormat":[{"large":"ignored"}]}}})"));require(g.size()==size,"vídeo retido");g.update(Json::parse(R"({"id":111,"info":{"props":{"unused":"ignored"},"params":{"EnumFormat":[{"large":"ignored"}]}}})"));require(!g.nodes.at(111).props.count("unused"),"propriedade irrelevante retida");});
    test("Cache: evento irrelevante não invalida o estado",[&](){Graph g=base;auto version=g.version;bool changed=g.update(Json::parse(R"({"id":111,"info":{"props":{"unused":"ignored"}}})"));require(!changed&&g.version==version,"estado invalidado sem mudança de áudio");});
    test("IDs: serial alterado bloqueia comando",[&](){Graph g=base;Ref ref=original.sink->ref;g.update(Json::parse("{\"id\":62,\"info\":{\"props\":{\"object.serial\":99999}}}"));Action a;a.refs={ref};a.value=20;rejects([&](){plan(g,a);});});
    test("IDs: remoção e reutilização não herdam parâmetros",[&](){Graph g=base;g.update(Json::parse("{\"id\":111}"));g.update(Json::parse(R"({"id":111,"type":"PipeWire:Interface:Node","info":{"props":{"object.serial":9999,"node.name":"novo","media.class":"Stream/Output/Audio"}}})"));require(g.nodes.at(111).props.count("application.name")==0&&!g.valid(original.apps()[0].nodes[0].ref),"objeto anterior herdado");});
    test("Volume: limitar a 100% sem desativar mudo",[&](){Action a;a.refs={original.apps()[0].nodes[0].ref};a.value=150;auto commands=plan(base,a);require(commands.size()==1&&commands[0].args==std::vector<std::string>{"wpctl","set-volume","111","100.00%","--limit","1.0"},"comando incorreto");});
    test("Volume: rejeitar referências sem serial",[&](){Action a;a.refs={original.sink->ref};a.refs[0].serial.clear();rejects([&](){plan(base,a);});});
    test("Porta desconectada: não produzir comando",[&](){Action a;a.kind=Action::Choose;a.choice=find_choice(original.outputs,"analog-output-headphones");rejects([&](){plan(base,a);});});
    test("Porta mudou após o clique: verificar disponibilidade novamente",[&](){Action a;a.kind=Action::Choose;a.choice=find_choice(original.outputs,"analog-output-speaker");Graph g=base;for(auto& r:g.devices.at(51).routes)if(r.name==a.choice.route_name)r.available="no";rejects([&](){plan(g,a);});});
    test("Microfone filtrado: rota já ativa não troca padrão",[&](){Action a;a.kind=Action::Choose;a.choice=find_choice(original.inputs,"analog-input-internal-mic");a.port_only=true;require(plan(base,a).empty(),"troca indevida do filtro");});
    test("Microfone filtrado: trocar apenas rota física",[&](){Action a;a.kind=Action::Choose;a.choice=find_choice(original.inputs,"analog-input-internal-mic");a.port_only=true;Graph g=base;for(auto& r:g.devices.at(51).current)if(r.device==0)r.index=1;auto c=plan(g,a);require(c.size()==1&&c[0].args==std::vector<std::string>{"wpctl","set-route","51","0"},"comando incorreto");});
    test("Saída por aplicativo: não trocar padrão nem rota compartilhada",[&](){Action a;a.kind=Action::Choose;for(const auto& c:original.outputs)if(c.node.name==original.sink->ref.name){a.choice=c;break;}a.choice.device.reset();a.choice.route=-1;a.refs={original.apps()[0].nodes[0].ref};auto c=plan(base,a);require(c.size()==1&&c[0].args[0]=="pw-metadata"&&c[0].args[5]==original.sink->ref.name,"roteamento incorreto");});
    test("Saída global: mover fluxos existentes",[&](){Action a;a.kind=Action::Choose;for(const auto& c:original.outputs)if(c.node.name==original.sink->ref.name){a.choice=c;break;}auto c=plan(base,a);require(c.size()==2&&c[0].args[1]=="set-default"&&c[1].args[0]=="pw-metadata","fluxos não movidos");});
    test("Acompanhar padrão: remover só target.object do aplicativo",[&](){Action a;a.kind=Action::FollowDefault;a.refs={original.apps()[0].nodes[0].ref};auto c=plan(base,a);require(c.size()==1&&c[0].args==std::vector<std::string>{"pw-metadata","-n","default","-d","111","target.object"},"remoção incorreta");});
    test("Mixer: agrupar fluxos pelo nome e PID",[&](){Graph g=base;Json e=Json::parse(R"({"id":112,"type":"PipeWire:Interface:Node","info":{"props":{"object.serial":9998,"node.name":"Firefox 2","application.name":"Firefox","application.process.id":6406,"media.class":"Stream/Output/Audio"}}})");g.update(e);require(g.state().apps().size()==1&&g.state().apps()[0].nodes.size()==2,"fluxos não agrupados");});
    test("Filtros: alvo por serial também identifica entrada física",[&](){Graph g=base;for(auto& kv:g.nodes)if(kv.second.ref.name=="capture.filtro_ruido_noise")kv.second.props["target.object"]=original.physical->ref.serial;require(g.state().physical&&g.state().physical->ref==original.physical->ref,"serial não resolvido");});
    test("Geometria: barra inferior, superior e lateral",[]{Rect a{0,0,1366,724};auto p=anchor(a,{1280,724,24,24},true,0,560,420,3);require(p.y==301&&p.x==744,"barra inferior");p=anchor({0,40,1366,728},{1280,0,24,40},true,0,560,420,3);require(p.y==43,"barra superior");p=anchor({40,0,1326,768},{0,680,40,24},true,1,560,420,3);require(p.x==43,"barra lateral");});
    test("Geometria: não sair de monitores com origem negativa",[]{Rect a{-1366,0,1366,724};auto p=anchor(a,{-5,730,24,24},true,0,560,450,3);require(p.x>=a.x&&p.x+p.width<=0&&p.y>=0&&p.y+p.height<=724,"fora do monitor");});
    test("Geometria: distância da barra usa a borda útil, mesmo com ícone recuado",[]{auto p=anchor({0,0,1366,724},{1250,744,24,24},true,0,560,420,3);require(p.y+p.height==721,"distância ignorada pelo recuo do ícone");});
    test("Mouse: margem e corredor, sem expandir área até outras janelas",[]{Rect p{800,300,560,420},i{1300,724,24,24};require(pointer_safe(p,i,{1310,722},4,true),"corredor ausente");require(pointer_safe(p,i,{798,400},4,true),"margem ausente");require(!pointer_safe(p,i,{500,400},4,true),"área excessiva");});
    test("Preferências: tema escuro padrão e limites válidos",[]{auto c=Config::from_json(Json::Object{});require(c.theme=="dark"&&c.layout==4&&c.hide_leave,"padrões incorretos");c=Config::from_json(Json::parse(R"({"layout":2,"opacity":0,"accent":"red; }","width":9999,"font":2})"));require(c.layout==4&&c.opacity==.7&&c.width==760&&c.font==11&&c.accent=="#91a8ff","validação insuficiente");});
    test("Teste de voz: primeiro segundo silencioso, impulso na posição exata",[]{VoiceDelay d;std::string sample(96002,0);sample[0]=0x34;sample[1]=0x12;std::string out=d.process(sample);require(std::all_of(out.begin(),out.begin()+96000,[](char c){return c==0;}),"vazamento antes do atraso");require(static_cast<unsigned char>(out[96000])==0x34&&static_cast<unsigned char>(out[96001])==0x12,"atraso diferente de 48000 amostras");});
    test("Teste de voz: chunks ímpares e limpeza do buffer",[]{VoiceDelay d;std::string out;out+=d.process(std::string("\x00",1));out+=d.process(std::string("\x80",1));near(d.peak,1);out+=d.process(std::string(95999,0));require(static_cast<unsigned char>(out[96000])==0,"primeiro byte atrasado");auto v=d.process(std::string(1,0));require(static_cast<unsigned char>(v[0])==0x80,"segundo byte perdido");d.clear();auto silence=d.process(std::string(96001,0));require(std::all_of(silence.begin(),silence.end(),[](char c){return c==0;}),"voz residual após parar");require(d.bytes()==96000,"buffer alterado");});
    test("Teste de voz: buffer permanece limitado após 20 segundos",[]{VoiceDelay d;std::string chunk(960,0);for(int i=0;i<2000;++i)d.process(chunk);require(d.bytes()==96000,"buffer cresceu");});
    test("Teste de voz: detectar troca de porta sem interromper por ajuste de volume",[&](){State s=original;for(const auto& n:s.nodes)if(n.ref.id==52)s.sink=n;auto before=connection_signature(s);s.sink->volume=.2;require(connection_signature(s)==before,"volume interrompeu o teste");for(auto& c:s.outputs)if(c.node==s.sink->ref){c.selected=c.route_name=="analog-output-headphones";c.available=true;}require(connection_signature(s)!=before,"troca P2/alto-falante não detectada");});
    test("KMix opcional: alterar só a chave raiz e restaurar texto",[]{std::string text="[0]\nMixer_Name_Key=PipeWire\n\n[General]\nAutostart=true\n";auto changed=change_root_value(text,"Autostart",std::string("false"));require(changed=="Autostart=false\n"+text,"chave fora da raiz");require(change_root_value(changed,"Autostart",std::nullopt)==text,"restauração mudou outras opções");});
    test("KMix opcional: preservar alterações posteriores e grupos",[]{std::string text="Autostart=true\n[General]\nAutostart=false\nPosition=1,2\n";require(root_value(text,"Autostart")==std::optional<std::string>("true"),"leu valor de grupo");auto s=change_root_value(text,"Autostart",std::string("false"));require(s=="Autostart=false\n[General]\nAutostart=false\nPosition=1,2\n","alterou outro grupo");});
    test("Desinstalação: preservar ZIP e arquivos pessoais",[]{
        std::string path=(folder()/"testes/remocao-XXXXXX").string();std::vector<char> b(path.begin(),path.end());b.push_back(0);if(!mkdtemp(b.data()))throw std::runtime_error("pasta de teste indisponível");fs::path temp(b.data());
        try{fs::copy_file(folder()/"audio-painel-rc",temp/"audio-painel-rc");atomic_write(temp/"IDENTIDADE-RC",std::string(APP_ID)+"\n");atomic_write(temp/"ARQUIVOS.txt","audio-painel-rc\nIDENTIDADE-RC\nARQUIVOS.txt\ncodigo.cpp\npacote.ZIP\n");atomic_write(temp/"codigo.cpp","código");atomic_write(temp/"pacote.ZIP","zip preservado");atomic_write(temp/"pessoal.txt","pessoal preservado");auto r=run_read({(temp/"audio-painel-rc").string(),"--desinstalar","--sim"});require(r.status==0,r.text);require(fs::exists(temp/"pacote.ZIP")&&fs::exists(temp/"pessoal.txt")&&!fs::exists(temp/"audio-painel-rc")&&!fs::exists(temp/"codigo.cpp"),"arquivo incorreto removido ou retido");fs::remove_all(temp);}catch(...){fs::remove_all(temp);throw;}
    });
    test("Desinstalação: recusar caminhos que saem da pasta",[]{
        std::string pattern=(folder()/"testes/protecao-XXXXXX").string();std::vector<char> b(pattern.begin(),pattern.end());b.push_back(0);if(!mkdtemp(b.data()))throw std::runtime_error("pasta de teste indisponível");fs::path temp(b.data()),app=temp/"app";fs::create_directory(app);
        try{fs::copy_file(folder()/"audio-painel-rc",app/"audio-painel-rc");atomic_write(app/"IDENTIDADE-RC",std::string(APP_ID)+"\n");atomic_write(app/"ARQUIVOS.txt","audio-painel-rc\n../pessoal.txt\n");atomic_write(temp/"pessoal.txt","preservar");auto r=run_read({(app/"audio-painel-rc").string(),"--desinstalar","--sim"});require(r.status!=0&&read_file(temp/"pessoal.txt")=="preservar"&&fs::exists(app/"audio-painel-rc"),"caminho externo não foi bloqueado");fs::remove_all(temp);}catch(...){fs::remove_all(temp);throw;}
    });
    test("Desinstalação: recusar subpasta substituída por link",[]{
        std::string pattern=(folder()/"testes/protecao-XXXXXX").string();std::vector<char> b(pattern.begin(),pattern.end());b.push_back(0);if(!mkdtemp(b.data()))throw std::runtime_error("pasta de teste indisponível");fs::path temp(b.data()),app=temp/"app";fs::create_directory(app);fs::create_directory(temp/"pessoal");
        try{fs::copy_file(folder()/"audio-painel-rc",app/"audio-painel-rc");atomic_write(app/"IDENTIDADE-RC",std::string(APP_ID)+"\n");atomic_write(app/"ARQUIVOS.txt","audio-painel-rc\ndados/arquivo.txt\n");atomic_write(temp/"pessoal/arquivo.txt","preservar");fs::create_directory_symlink(temp/"pessoal",app/"dados");auto r=run_read({(app/"audio-painel-rc").string(),"--desinstalar","--sim"});require(r.status!=0&&read_file(temp/"pessoal/arquivo.txt")=="preservar"&&fs::exists(app/"audio-painel-rc"),"link externo não foi bloqueado");fs::remove_all(temp);}catch(...){fs::remove_all(temp);throw;}
    });
    std::cout<<"\n"<<passed<<" teste(s) passaram; "<<failed<<" falharam. Nenhum comando de alteração de áudio foi executado.\n";return failed?1:0;
}
}
